const $=s=>document.querySelector(s);
const recipes=[
{id:'fried-rice',name:'Garlic & egg fried rice',time:15,emoji:'🍳',ingredients:['rice','eggs','garlic','soy sauce','oil'],amounts:['2 cups cooked, cooled rice','2 eggs','3 cloves garlic, minced','1 tablespoon soy sauce','1 tablespoon cooking oil'],steps:['Break up any clumps in the cooked rice. Beat the eggs in a small bowl.','Heat half the oil in a large pan over medium heat. Add the eggs and scramble until set, then transfer to a plate.','Add the remaining oil and garlic. Stir for 30 seconds, then add rice and stir-fry for 4–5 minutes until steaming hot throughout.','Return the eggs to the pan, add soy sauce, and toss for another minute. Serve straight away.']},
{id:'tomato-pasta',name:'Easy tomato & garlic pasta',time:25,emoji:'🍝',ingredients:['pasta','tomatoes','garlic','oil','salt','pepper'],amounts:['180 g pasta','3 ripe tomatoes, chopped','3 garlic cloves, minced','2 tablespoons oil','Salt, to taste','Black pepper, to taste'],steps:['Bring a pan of salted water to a boil. Cook the pasta according to its package directions. Save half a cup of pasta water before draining.','Heat oil in a skillet over medium-low heat. Add garlic and stir for 30 seconds.','Add tomatoes, salt, and pepper. Simmer for 12–15 minutes, stirring and crushing the tomatoes with a spoon.','Toss in the pasta. Add a splash of the reserved water to loosen the sauce, then serve.']},
{id:'omelette',name:'Spinach & cheese omelette',time:10,emoji:'🥬',ingredients:['eggs','spinach','cheese','oil','salt','pepper'],amounts:['4 eggs','2 handfuls spinach','½ cup grated cheese','1 tablespoon oil','Salt, to taste','Black pepper, to taste'],steps:['Whisk the eggs with a pinch of salt and pepper.','Heat half the oil in a nonstick pan. Wilt the spinach for 1–2 minutes, then set aside.','Add the remaining oil and beaten eggs. Cook over medium-low heat, gently pulling the edges toward the middle so uncooked egg flows underneath.','When the eggs are nearly set, add spinach and cheese to one half. Fold over and cook until the egg is set and cheese melts. Divide between two plates.']},
{id:'potato-hash',name:'Golden potato & egg hash',time:30,emoji:'🥔',ingredients:['potatoes','onion','eggs','oil','salt','pepper'],amounts:['2 medium potatoes, diced small','1 onion, diced','2 eggs','2 tablespoons oil','Salt, to taste','Black pepper, to taste'],steps:['Boil the diced potatoes for 6–8 minutes until just tender, then drain well.','Heat oil in a wide skillet. Add potatoes and onion and cook for 10–12 minutes, turning occasionally until golden.','Season, then make two small spaces in the potatoes. Crack an egg into each.','Cover the pan and cook on low until the whites and yolks are set. Serve hot.']},
{id:'cucumber-salad',name:'Crunchy tomato cucumber salad',time:10,emoji:'🥗',ingredients:['cucumber','tomatoes','onion','lemon','oil','salt'],amounts:['1 cucumber, chopped','2 tomatoes, chopped','½ onion, thinly sliced','Juice of ½ lemon','1 tablespoon oil','Salt, to taste'],steps:['Chop the cucumber and tomatoes into bite-size pieces. Thinly slice the onion.','Whisk the lemon juice, oil, and salt together in a bowl.','Add the vegetables and toss gently. Taste and adjust the seasoning, then serve.']},
{id:'chickpea-skillet',name:'Tomato chickpea skillet',time:20,emoji:'🍲',ingredients:['chickpeas','tomatoes','spinach','garlic','oil','salt','pepper'],amounts:['1 can chickpeas, drained','3 tomatoes, chopped','2 handfuls spinach','2 garlic cloves, minced','1 tablespoon oil','Salt, to taste','Black pepper, to taste'],steps:['Warm oil in a skillet over medium heat. Add garlic and stir for 30 seconds.','Add chopped tomatoes, salt, and pepper. Simmer for 8–10 minutes until softened.','Stir in the drained chickpeas and simmer for 5 minutes.','Fold in spinach and cook until wilted. Serve in bowls.']},
{id:'toast',name:'Cheesy tomato toast',time:10,emoji:'🍞',ingredients:['bread','tomatoes','cheese','pepper'],amounts:['4 slices bread','2 tomatoes, sliced','½ cup grated cheese','Black pepper, to taste'],steps:['Toast the bread lightly on both sides.','Top with sliced tomatoes, cheese, and a little pepper.','Place under a hot grill or broiler until the cheese melts, watching closely to avoid burning. Serve hot.']},
{id:'mushrooms',name:'Garlic mushroom rice bowl',time:15,emoji:'🍄',ingredients:['mushrooms','rice','garlic','soy sauce','oil'],amounts:['200 g mushrooms, sliced','2 cups cooked rice','2 garlic cloves, minced','1 tablespoon soy sauce','1 tablespoon oil'],steps:['Heat the oil in a skillet over medium-high heat. Add the mushrooms and cook for 6–8 minutes until golden.','Add garlic and stir for 30 seconds. Add soy sauce and a tablespoon of water.','Add the cooked rice and stir-fry until steaming hot throughout. Divide into bowls.']}
];
const alias={'egg':'eggs','tomato':'tomatoes','potato':'potatoes','onions':'onion','clove of garlic':'garlic','garlic cloves':'garlic','cooked rice':'rice','white rice':'rice','olive oil':'oil','vegetable oil':'oil','cooking oil':'oil','black pepper':'pepper','mushroom':'mushrooms','chickpea':'chickpeas','canned chickpeas':'chickpeas','lemons':'lemon','cucumbers':'cucumber'};
const normalize=v=>{const s=v.trim().toLowerCase().replace(/\s+/g,' ');return alias[s]||s};
let ingredients=[],hasSearched=false;
const quick=['🥚|Eggs','🍅|Tomatoes','🥬|Spinach','🧀|Cheese','🍚|Rice','🧄|Garlic','🥔|Potatoes','🍝|Pasta','🍄|Mushrooms','🧅|Onion','🥒|Cucumber','🥫|Chickpeas','🍞|Bread','🍋|Lemon','🥢|Soy sauce'];
function available(){return new Set([...ingredients,...($('#staples').checked?['oil','salt','pepper']:[])])}
function ranked(){const have=available();return recipes.map(r=>({...r,missing:r.ingredients.filter(i=>!have.has(i)),matched:r.ingredients.filter(i=>ingredients.includes(i)).length})).sort((a,b)=>a.missing.length-b.missing.length||b.matched-a.matched||a.time-b.time)}
function renderIngredients(){$('#count').textContent=ingredients.length;$('#chips').replaceChildren(...ingredients.map(i=>{const b=document.createElement('button');b.className='chip';b.textContent=i;const x=document.createElement('span');x.textContent='×';b.append(x);b.setAttribute('aria-label','Remove '+i);b.onclick=()=>{ingredients=ingredients.filter(v=>v!==i);renderIngredients();renderResults()};return b}));$('#quick').replaceChildren(...quick.filter(v=>!ingredients.includes(normalize(v.split('|')[1]))).map(v=>{const [emoji,name]=v.split('|');const b=document.createElement('button');b.textContent=emoji+' '+name;b.onclick=()=>add(name);return b}));}
function add(value){const values=value.split(',').map(normalize).filter(Boolean);for(const v of values){if(v.length<=60&&!ingredients.includes(v))ingredients.push(v)}$('#ingredient').value='';$('#notice').textContent='';renderIngredients();renderResults()}
function renderResults(){const active=hasSearched||ingredients.length>0;let list=active?ranked().filter(r=>r.matched>0):recipes.slice(0,3).map(r=>({...r,missing:[]}));if($('#ready').checked)list=active?list.filter(r=>r.missing.length===0):[];$('#result-title').textContent=active?'Here’s what you could cook':'A little fridge inspiration';$('#summary').textContent=active?`${list.length} ${list.length===1?'idea':'ideas'} from our recipe collection · Best matches first`:'Start with your ingredients, or try one of these simple favorites.';$('#recipes').replaceChildren();if(!list.length){$('#recipes').innerHTML='<div class="empty"><h3>'+(!ingredients.length?'Let’s start with your fridge':'No matching meals just yet')+'</h3><p>'+(!ingredients.length?'Add a few ingredients to see what you can make.':$('#ready').checked?'Try turning off “Ready to cook only” to see meals with a few missing ingredients.':'Try adding another ingredient. Our starter collection includes rice, pasta, eggs, vegetables, and chickpeas.')+'</p></div>';return}list.forEach((r,index)=>{const card=document.createElement('article');card.className='recipe-card';const art=document.createElement('div');art.className='recipe-art';art.innerHTML='<span class="food-symbol" aria-hidden="true">'+r.emoji+'</span>';if(!active&&index===0){const img=document.createElement('img');img.src='https://images.unsplash.com/photo-1771762211132-2f0598b44dbb?auto=format&fit=crop&w=600&q=85';img.alt='Fresh vegetables prepared for cooking';img.onerror=()=>img.remove();art.append(img)}const body=document.createElement('div');body.className='recipe-body';body.innerHTML=`<div class="recipe-top"><span class="badge ${active&&r.missing.length?'missing':''}">${!active?'SIMPLE FAVORITE':r.missing.length?'NEEDS '+r.missing.length+' MORE':'READY TO COOK'}</span><span class="time">◷ ${r.time} min · 2 servings</span></div><h3>${r.name}</h3><p></p><button class="recipe-link">View recipe ↗</button>`;body.querySelector('p').textContent=active?(r.missing.length?'Missing: '+r.missing.join(', '):'You have everything you need.') : r.ingredients.filter(i=>!['oil','salt','pepper'].includes(i)).join(' · ');body.querySelector('button').onclick=()=>openRecipe(r.id);card.append(art,body);$('#recipes').append(card)})}
function openRecipe(id){const r=recipes.find(r=>r.id===id),have=available();$('#recipe-detail').innerHTML=`<span class="badge">${r.time} MINUTES · SERVES 2</span><h2>${r.name}</h2><h3>Ingredients</h3><ul>${r.ingredients.map((i,n)=>`<li class="${have.has(i)?'have':'need'}">${r.amounts[n]} ${have.has(i)?'✓':'— missing'}</li>`).join('')}</ul><h3>Let’s cook</h3><ol>${r.steps.map(s=>'<li>'+s+'</li>').join('')}</ol>`;$('#recipe-dialog').showModal()}
$('#add-form').onsubmit=e=>{e.preventDefault();add($('#ingredient').value)};$('#find').onclick=()=>{hasSearched=true;renderResults();$('#notice').textContent=ingredients.length?'Suggestions updated. Time to pick something good.':'Add your ingredients above to get started.';if(innerWidth<760&&ingredients.length)document.querySelector('.results').scrollIntoView({behavior:'smooth'})};$('#clear').onclick=()=>{ingredients=[];hasSearched=false;$('#ready').checked=false;$('#notice').textContent='';renderIngredients();renderResults()};$('#staples').onchange=renderResults;$('#ready').onchange=renderResults;$('#close-dialog').onclick=()=>$('#recipe-dialog').close();$('#recipe-dialog').onclick=e=>{if(e.target===$('#recipe-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};renderIngredients();renderResults();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_fridge_ingredients',description:'Replace the visible ingredient list and return matching recipes.',inputSchema:{type:'object',properties:{ingredients:{type:'array',items:{type:'string',minLength:1,maxLength:60},maxItems:100}},required:['ingredients'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Array.isArray(input.ingredients)||input.ingredients.length>100||input.ingredients.some(i=>typeof i!=='string'||!i.trim()||i.length>60))throw new Error('Provide an array of up to 100 ingredient names.');ingredients=[...new Set(input.ingredients.map(normalize))];hasSearched=true;renderIngredients();renderResults();return{ingredients,recipes:ranked().filter(r=>r.matched>0).map(r=>({name:r.name,missing:r.missing,minutes:r.time}))}}})).catch(()=>{})}catch{}}
